// The pipeline.intake_sent event carries only lead_id (envelope: { event,
// delivery_id, timestamp, payload: { lead_id, from_status, to_status, trigger } }).
// We deliberately do NOT carry provider data through n8n: the CRM's
// /intake-completed callback sources provider identifiers from the lead's stored
// fields, so there is nothing to invent here and no PII flows through the
// orchestrator. We just forward the lead_id.
const payload = $json.payload || $json;
const leadId = payload.lead_id ?? payload.lead?.id;
if (!leadId) {
  throw new Error('pipeline.intake_sent payload missing lead_id — cannot orchestrate pipeline');
}
return [{ json: { lead_id: leadId } }];
